(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.OneStepGarden=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
  'use strict';
  const stages=[{at:0,name:'작은 씨앗',message:'작은 한 걸음이 귤나무의 시작이에요.'},{at:1,name:'초록 새싹',message:'첫 잎이 났어요. 내 속도로 자라고 있어요.'},{at:3,name:'튼튼한 나무',message:'한 걸음씩, 가지가 조금 더 단단해졌어요.'},{at:5,name:'하얀 귤꽃',message:'차곡차곡 쌓인 걸음 위로 꽃이 피었어요.'},{at:8,name:'달콤한 귤',message:'드디어 귤이 열렸어요. 오늘도 같이 한 걸음!'}];
  const valid=id=>typeof id==='string'&&id.length>0&&id.length<=150;
  function normalize(saved,tasks=[]){const awarded=Array.isArray(saved?.awarded)?saved.awarded:[];return{awarded:[...new Set([...awarded,...tasks.filter(t=>t.status==='done').map(t=>t.id)].filter(valid))]};}
  function award(garden,id){if(!valid(id)||garden.awarded.includes(id))return false;garden.awarded.push(id);return true;}
  function stageFor(count){let index=0;stages.forEach((s,i)=>{if(count>=s.at)index=i});return index;}
  function status(garden){const count=garden.awarded.length,index=stageFor(count),stage=stages[index],next=stages[index+1];return{count,index,...stage,next,progress:next?(count-stage.at)/(next.at-stage.at):1};}
  function mascot(x=390,y=148,scale=1){return`<g class="gyul-character" transform="translate(${x} ${y}) scale(${scale})"><ellipse cx="0" cy="56" rx="46" ry="8" fill="#d8d6ba" opacity=".35"/><g class="gyul-bounce"><path d="M-29 18 Q-56 13-53 25M30 17Q55 10 52 23" stroke="#a95428" stroke-width="4" fill="none" stroke-linecap="round"/><path d="M-16 43L-21 53M16 43L21 53" stroke="#a95428" stroke-width="5" stroke-linecap="round"/><path d="M0-39C-53-46-59 18-30 39C-12 54 23 48 37 28C57-3 35-43 0-39Z" fill="#ffa73b" stroke="#b75c2b" stroke-width="2.5"/><path d="M-29-20Q-38-4-31 9" stroke="#ffd480" stroke-width="7" fill="none" stroke-linecap="round"/><path d="M0-40Q1-53 12-56" stroke="#6d6b36" stroke-width="3.5" fill="none" stroke-linecap="round"/><path d="M3-45Q10-67 34-56Q25-36 3-45Z" fill="#648b50" stroke="#456b3e" stroke-width="2"/><circle cx="-12" cy="2" r="3.2" fill="#653e2d"/><circle cx="12" cy="2" r="3.2" fill="#653e2d"/><path d="M-5 13Q0 19 5 13" stroke="#653e2d" stroke-width="2.5" fill="none" stroke-linecap="round"/><ellipse cx="-22" cy="13" rx="7" ry="4" fill="#ed8361" opacity=".6"/><ellipse cx="22" cy="13" rx="7" ry="4" fill="#ed8361" opacity=".6"/><g fill="#e88930"><circle cx="-10" cy="32" r="1.5"/><circle cx="3" cy="35" r="1.5"/><circle cx="20" cy="28" r="1.5"/></g></g></g>`;}
  function flower(x,y){return`<g transform="translate(${x} ${y})"><g fill="#fffaf1" stroke="#e5d6a8" stroke-width=".8"><ellipse cy="-5" rx="4" ry="6"/><ellipse cy="-5" rx="4" ry="6" transform="rotate(72)"/><ellipse cy="-5" rx="4" ry="6" transform="rotate(144)"/><ellipse cy="-5" rx="4" ry="6" transform="rotate(216)"/><ellipse cy="-5" rx="4" ry="6" transform="rotate(288)"/></g><circle r="3" fill="#e9b84b"/></g>`;}
  function fruit(x,y,r=12){return`<g class="garden-fruit" transform="translate(${x} ${y})"><circle r="${r}" fill="#ffa337" stroke="#dc802c" stroke-width="1.3"/><path d="M-1-${r}q5-8 12-5q-2 8-12 5" fill="#426d45"/><path d="M-${r*.45}-${r*.3}q-2 4-1 7" fill="none" stroke="#ffd18b" stroke-width="3" stroke-linecap="round"/></g>`;}
  function scene(index=0){index=Math.max(0,Math.min(4,Number(index)||0));let plant='';if(index===0)plant='<ellipse cx="205" cy="188" rx="13" ry="8" transform="rotate(-22 205 188)" fill="#b18352" stroke="#80623f" stroke-width="2"/><path d="M202 182l4 12" stroke="#e7c597" stroke-width="2"/>';
    if(index===1)plant='<path d="M205 190Q203 163 208 144" fill="none" stroke="#66844a" stroke-width="5" stroke-linecap="round"/><path d="M205 170Q172 168 178 145Q202 141 205 170M207 158Q210 130 235 135Q240 158 207 158" fill="#91ad64" stroke="#64834b" stroke-width="2"/>';
    if(index>=2){plant='<path d="M205 192V125M205 155l-26-24M205 142l27-25" stroke="#9a744e" stroke-width="11" fill="none" stroke-linecap="round"/><path d="M205 192V125" stroke="#b18a5c" stroke-width="4" stroke-linecap="round"/><path d="M144 140C119 120 139 88 161 88C150 54 184 40 206 54C232 29 266 52 262 79C296 83 300 119 278 135C265 154 242 150 225 144C202 161 183 148 171 148C158 155 145 151 144 140Z" fill="#799a59" stroke="#5b7d48" stroke-width="2"/><path d="M154 107Q144 90 162 81M181 70Q198 58 207 70M246 61Q261 69 256 83" stroke="#a5bc79" stroke-width="8" fill="none" stroke-linecap="round"/><g fill="#a3b874"><ellipse cx="158" cy="128" rx="10" ry="5" transform="rotate(25 158 128)"/><ellipse cx="252" cy="133" rx="9" ry="5" transform="rotate(-30 252 133)"/></g>';
      if(index===3)plant+=flower(167,100)+flower(228,78)+flower(252,117)+flower(196,132)+flower(205,99);
      if(index===4)plant+=fruit(161,109,13)+fruit(204,78,14)+fruit(254,105,13)+fruit(226,132,15)+fruit(180,137,10);}
    return`<svg class="garden-art" viewBox="0 0 520 238" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${stages[index].name} 단계의 귤 정원과 귤 캐릭터 귤이"><circle cx="417" cy="37" r="20" fill="#f6d78a" opacity=".7"/><path d="M21 113Q82 95 111 111L129 111Q178 86 225 110Q302 82 349 111Q405 99 499 114V214H21Z" fill="#e8ebcf"/><path d="M38 169Q103 159 139 169M335 168Q379 159 461 170" stroke="#cbd5bc" fill="none" stroke-width="2"/><path d="M17 193Q166 179 264 190T501 190" stroke="#a3bbb0" fill="none" stroke-width="2"/><ellipse cx="205" cy="197" rx="66" ry="9" fill="#c0b396" opacity=".3"/><g class="garden-plant">${plant}</g>${mascot(390,146,.82)}<g fill="#8b8a7a"><path d="M53 195Q51 181 62 182Q76 180 80 195Z"/><path d="M82 194Q83 185 93 187Q102 183 106 194Z"/><path d="M275 196Q277 187 288 188Q301 185 303 197Z"/></g><g fill="#f8f8e8"><circle cx="62" cy="186" r="1.3"/><circle cx="69" cy="191" r="1.5"/><circle cx="91" cy="190" r="1"/></g><g class="garden-sparkles" stroke="#d6a24a" stroke-width="2" stroke-linecap="round"><path d="M305 68v10m-5-5h10M118 73v8m-4-4h8M320 123v8m-4-4h8"/></g></svg>`;
  }
  return{stages,normalize,award,stageFor,status,mascot,scene};
});
